function glyphInkMap(raw: string, font: string, weight: number, italic: boolean, spacingEm: number): { pts: [number, number][]; w: number } | null {
  const key = `${raw}|${font}|${weight}|${italic}|${spacingEm.toFixed(3)}`;
  const hit = _inkCache.get(key);
  if (hit !== undefined) return hit;
  let out: { pts: [number, number][]; w: number } | null = null;
  try {
    if (typeof document !== "undefined") {
      const cv = document.createElement("canvas");
      const spec = `${italic ? "italic " : ""}${weight || 400} ${INK_FS}px "${font}", 'Inter Variable', Inter, sans-serif`;
      const pre = cv.getContext("2d");
      if (pre) {
        pre.font = spec;
        cv.width = Math.min(2400, Math.ceil(pre.measureText(raw).width * (1 + Math.max(0, spacingEm))) + INK_FS);
        cv.height = INK_FS * 2;
        const ctx = cv.getContext("2d", { willReadFrequently: true })!;
        ctx.font = spec; // canvas resize resets state
        try { (ctx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = `${spacingEm}em`; } catch { /* older engines */ }
        ctx.textBaseline = "middle";
        ctx.fillStyle = "#fff";
        ctx.fillText(raw, INK_FS / 2, INK_FS);
        const tw = ctx.measureText(raw).width;
        const img = ctx.getImageData(0, 0, cv.width, cv.height).data;
        const pts: [number, number][] = [];
        for (let py = 0; py < cv.height; py += 3) for (let px = 0; px < cv.width; px += 3) {
          if (img[(py * cv.width + px) * 4 + 3] > 128) pts.push([px - INK_FS / 2, py - INK_FS]);
        }
        if (pts.length && tw > 0) out = { pts, w: tw };
      }
    }
  } catch { out = null; }
  /* a sample taken before the face finished loading measured the FALLBACK
     font's letterforms — usable this render, but NEVER cached, or the
     stars keep the wrong glyph run forever even after the real face lands
     (owner: "are the stars drifting away from the letterforms?").
     fonts.check() alone can't gate this: it answers TRUE for a family
     with nothing registered (nothing pending to load) — exactly the
     pre-ensureFont window. Ready = the family is actually registered in
     document.fonts AND its load settled. */
  let ready = true;
  try {
    const fam = font.toLowerCase();
    const registered = [...document.fonts].some((f) => f.family.replace(/['"]/g, "").toLowerCase() === fam);
    ready = registered && document.fonts.check(`${weight || 400} ${INK_FS}px "${font}"`);
  } catch { /* engines without FontFaceSet iteration: cache as before */ }
  if (ready) {
    if (_inkCache.size > 300) _inkCache.clear();
    _inkCache.set(key, out);
  }
  return out;
}

/* Rough.js draws the hand-drawn *line character* over the approved outline —
   it never designs the silhouette. Fixed seed keeps every render, state card,
   copied code and download byte-identical. Results are memoized per path. */
let roughGen: ReturnType<typeof rough.generator> | null = null;
const inkCache = new Map<string, string>();
function roughInk(d: string, color: string, sw: number): string {
  const key = `${d}|${color}|${sw}`;
  const hit = inkCache.get(key);
  if (hit !== undefined) return hit;
  roughGen ??= rough.generator();
  const drawable = roughGen.path(d, { seed: 7, roughness: 1.7, bowing: 0.9 });
  const out = `<g data-layer="ink" opacity="0.8">` + roughGen.toPaths(drawable)
    .map((p) => `<path d="${p.d}" fill="none" stroke="${color}" stroke-width="${sw.toFixed(1)}" stroke-linecap="round"/>`)
    .join("") + `</g>`;
  if (inkCache.size > 80) inkCache.clear();
  inkCache.set(key, out);
  return out;
}

// Candy engine v9 — a hard-candy shell built from ordered, independently
// tokenized layers:
//   1 cast shadow   2 extrusion   3 outer rim   4 bevel wall   5 face gradient
//   6 inner edge    7 inner glow  8 curved gloss 9 sharp specular
//   10 lower bloom  11 micro texture  12 text & icon treatment
// Pure (config, state) → SVG string for canvas + copy + exports. The lighting
// angle is the single source of truth: every gradient, the shadow direction,
// the gloss side and the specular position derive from it.

