              for (const p of ink.pts) {
                const d = (p[0] - sx) * (p[0] - sx) + (p[1] - sy) * (p[1] - sy);
                if (d < bd) { bd = d; best = p; }
              }
              if (best) { nx = startX + (best[0] / INK_FS) * fs; ny = gy + (best[1] / INK_FS) * fs; }
