      const titleTxt = opts.label ?? "QUEST COMPLETE";
      const title = contentText(titleTxt, 42 + w / 2, 33 + inset + 34 * k, fitFs(titleTxt, 38 * k * typeK, w - inset * 2 - 24 * k), { anchor: "middle" });
